import type { LucideIcon } from 'lucide-react'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { MarketingSiteLink } from '@/components/global/shared/MarketingSiteLink'
import { PUBLIC_ICON_MUTED_CLASSES } from '@/lib/public-icon-classes'
import { cn } from '@/lib/utils'
import { useT } from '@/lib/i18n/translate'

export type ProductAvatarItem = {
  name: string
  icon?: LucideIcon
  imageSrc?: string
  label?: string
  href?: string
}

type ProductAvatarsListProps = {
  items: readonly ProductAvatarItem[]
  className?: string
  ariaLabel?: string
}

const avatarClassName = cn(
  'flex size-9 items-center justify-center rounded-full border border-muted-foreground/6 bg-muted-foreground/[0.025] shadow-none backdrop-blur-sm transition-[border-color,opacity,transform] duration-300 dark:bg-muted/10',
  'ring-1 ring-background',
  'hover:z-10 hover:scale-105 hover:border-muted-foreground/10 hover:bg-muted-foreground/[0.04] sm:size-10',
)

const iconClassName = 'size-4 text-muted-foreground/70 sm:size-[17px]'

export function ProductAvatarsList({
  items,
  className,
  ariaLabel,
}: ProductAvatarsListProps) {
  const t = useT()
  return (
    <ul
      className={cn('inline-flex items-center justify-center ps-0', className)}
      aria-label={ariaLabel ? t(ariaLabel) : undefined}
    >
      {items.map((item, index) => {
        const Icon = item.icon
        const avatarContent = item.label ? (
          <span className="text-[11px] font-medium text-muted-foreground/80 sm:text-[12px]">
            {item.label}
          </span>
        ) : item.imageSrc ? (
          <img
            src={item.imageSrc}
            alt=""
            className={cn(
              'size-4 object-contain sm:size-[17px]',
              PUBLIC_ICON_MUTED_CLASSES,
            )}
          />
        ) : Icon ? (
          <Icon className={iconClassName} strokeWidth={1.5} aria-hidden />
        ) : null

        return (
          <li
            key={item.name}
            className={cn('relative shrink-0', index > 0 && '-ms-2 sm:-ms-2.5')}
            style={{ zIndex: items.length - index }}
          >
            <Tooltip>
              <TooltipTrigger asChild>
                {item.href ? (
                  <MarketingSiteLink
                    href={item.href}
                    className={cn(avatarClassName, 'cursor-pointer')}
                    aria-label={t(item.name)}
                  >
                    {avatarContent}
                  </MarketingSiteLink>
                ) : (
                  <div
                    className={cn(avatarClassName, 'cursor-default')}
                    aria-label={t(item.name)}
                  >
                    {avatarContent}
                  </div>
                )}
              </TooltipTrigger>
              <TooltipContent side="bottom" className="text-[12px]">
                {t(item.name)}
              </TooltipContent>
            </Tooltip>
          </li>
        )
      })}
    </ul>
  )
}
import type { LucideIcon } from 'lucide-react'
import { ANALYTICS_PRODUCT_ICON } from '@/lib/analytics/product-icon'
import {
  Database,
  Folder,
  Globe,
  Globe2,
  MessageSquare,
  Radio,
  ScanSearch,
  Search,
  Shield,
  Users,
  Zap,
} from 'lucide-react'
import { PRODUCT_NAV_REGISTRY } from '@/lib/products/registry'

export type PricingService = {
  name: string
  icon: LucideIcon
}

const ALL_PRICING_SERVICES: readonly PricingService[] = [
  { name: 'Auth', icon: Users },
  { name: 'Databases', icon: Database },
  { name: 'Storage', icon: Folder },
  { name: 'Functions', icon: Zap },
  { name: 'Messaging', icon: MessageSquare },
  { name: 'Realtime', icon: Radio },
  { name: 'Sites', icon: Globe },
  { name: 'Domains', icon: Search },
  { name: 'Network', icon: Globe2 },
  { name: 'Firewall', icon: Shield },
  { name: 'Advisor', icon: ScanSearch },
  { name: 'Analytics', icon: ANALYTICS_PRODUCT_ICON },
]

function isPricingServiceComingSoon(name: string) {
  const navItem = Object.values(PRODUCT_NAV_REGISTRY).find((item) => item.name === name)
  return navItem?.comingSoon === true
}

export const pricingServices: readonly PricingService[] = ALL_PRICING_SERVICES.filter(
  (service) => !isPricingServiceComingSoon(service.name),
)

export function formatPricingServiceList() {
  const names = pricingServices.map((service) => service.name)
  if (names.length === 0) return ''
  if (names.length === 1) return names[0]
  return `${names.slice(0, -1).join(', ')}, and ${names[names.length - 1]}`
}
import { ArrowDown, ArrowRight, ArrowUpRight, Globe } from 'lucide-react'
import { Fragment } from 'react'
import { ProductAvatarsList } from '@/components/global/shared/ProductAvatarsList'
import { useT } from '@/lib/i18n/translate'
import { pricingServices } from '@/lib/pricing/services'
import { cn } from '@/lib/utils'

export type MarketingProductPill = {
  label: string
  href: string
}

type MarketingProductPillsProps = {
  build: readonly MarketingProductPill[]
  deploy?: readonly MarketingProductPill[]
  protect?: readonly MarketingProductPill[]
  scale?: {
    href?: string
  }
  className?: string
}

function getProductIcon(label: string) {
  return (
    pricingServices.find((service) => service.name === label)?.icon ??
    Globe
  )
}

function toAvatarItems(products: readonly MarketingProductPill[]) {
  return products.map((product) => ({
    name: product.label,
    icon: getProductIcon(product.label),
    href: product.href,
  }))
}

function ProductAvatarGroup({
  label,
  products,
}: {
  label: string
  products: readonly MarketingProductPill[]
}) {
  const t = useT()
  return (
    <div className="flex flex-nowrap items-center gap-2.5 sm:gap-3">
      <p className="shrink-0 text-[11px] font-semibold uppercase tracking-[0.2em] text-muted-foreground">
        {t(label)}
      </p>
      <ProductAvatarsList
        items={toAvatarItems(products)}
        ariaLabel={`${t(label)} ${t('products')}`}
      />
    </div>
  )
}

function ScaleAvatarGroup({ href }: { href?: string }) {
  const t = useT()
  return (
    <div className="flex flex-nowrap items-center gap-2.5 sm:gap-3">
      <p className="shrink-0 text-[11px] font-semibold uppercase tracking-[0.2em] text-muted-foreground">
        {t('Scale')}
      </p>
      <ProductAvatarsList
        items={[{ name: t('Scale'), icon: ArrowUpRight, href }]}
        ariaLabel={t('Scale')}
      />
    </div>
  )
}

function GroupArrow() {
  return (
    <div
      className="flex h-9 shrink-0 items-center justify-center sm:h-10"
      aria-hidden
    >
      <ArrowRight
        className="hidden size-4 text-muted-foreground/50 sm:block"
        strokeWidth={1.5}
      />
      <ArrowDown
        className="size-4 text-muted-foreground/50 sm:hidden"
        strokeWidth={1.5}
      />
    </div>
  )
}

export function MarketingProductPills({
  build,
  deploy,
  protect,
  scale,
  className,
}: MarketingProductPillsProps) {
  const productGroups = [
    { label: 'Build', products: build },
    ...(deploy?.length ? [{ label: 'Deploy' as const, products: deploy }] : []),
    ...(protect?.length
      ? [
          {
            // Analytics joins Firewall here once its feature flag is on.
            label: protect.some((product) => product.href === '/products/analytics')
              ? 'Observe & protect'
              : 'Protect',
            products: protect,
          },
        ]
      : []),
  ]

  return (
    <div
      className={cn(
        'mt-10 flex flex-col items-center justify-center gap-5 sm:flex-row sm:flex-wrap sm:items-center sm:justify-center sm:gap-x-4 sm:gap-y-3 lg:gap-x-6',
        className,
      )}
    >
      {productGroups.map((group, index) => (
        <Fragment key={group.label}>
          {index > 0 ? <GroupArrow /> : null}
          <ProductAvatarGroup label={group.label} products={group.products} />
        </Fragment>
      ))}
      {scale ? (
        <>
          {productGroups.length > 0 ? <GroupArrow /> : null}
          <ScaleAvatarGroup href={scale.href} />
        </>
      ) : null}
    </div>
  )
}
import {
  isPricingPlanGridReady,
  shouldShowStartPlan,
} from '@/lib/pricing/visitor-country-resolution'
import {
  useVisitorCountryCode,
  useVisitorCountryResolutionComplete,
} from '@/hooks/use-visitor-country'

/**
 * Whether to show the Start plan. The pricing grid stays empty until locale is
 * known on the client (after hydration) so we never paint 3 plans then swap to 4.
 */
export function useStartPlanVisibility(): {
  ready: boolean
  showStartPlan: boolean
} {
  const countryCode = useVisitorCountryCode()
  const resolutionComplete = useVisitorCountryResolutionComplete()
  const ready = isPricingPlanGridReady(countryCode, resolutionComplete)

  return {
    ready,
    showStartPlan: shouldShowStartPlan(ready, countryCode),
  }
}
import type { ComparisonTable, PlanId, PricingPlan } from './types'

/**
 * Analytics pricing is shown only while the `analytics` feature flag is on.
 * Keep in step with `analyticsEvents` in the cloud repo's app/config/plans.php
 * and the per-100K overage in app/config/plans/usage.php.
 */
export const ANALYTICS_COMPARISON_TABLE_TITLE = 'Analytics'

const ANALYTICS_PLAN_FEATURES: Partial<Record<PlanId, string>> = {
  free: '50K analytics events',
  start: '50K analytics events',
  pro: '100K analytics events',
}

/** Bullet the analytics allowance goes after, so it sits with the other usage limits. */
const ANALYTICS_FEATURE_ANCHOR = /monthly active users/i

export function withAnalyticsPlanFeatures(
  plans: readonly PricingPlan[],
  enabled: boolean,
): PricingPlan[] {
  if (!enabled) return [...plans]
  return plans.map((plan) => {
    const feature = ANALYTICS_PLAN_FEATURES[plan.id]
    if (!feature) return plan
    const features = [...plan.features]
    const anchor = features.findIndex((item) => ANALYTICS_FEATURE_ANCHOR.test(item))
    features.splice(anchor === -1 ? features.length : anchor + 1, 0, feature)
    return { ...plan, features }
  })
}

export function withAnalyticsComparison<T extends { title: string }>(
  tables: readonly T[],
  enabled: boolean,
): T[] {
  return enabled
    ? [...tables]
    : tables.filter((table) => table.title !== ANALYTICS_COMPARISON_TABLE_TITLE)
}

export type { ComparisonTable }
import { Link } from '@tanstack/react-router'
import { Check, Info } from 'lucide-react'
import type { ReactNode } from 'react'
import { Button } from '@/components/ui/button'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { useT } from '@/lib/i18n/translate'
import { SALES_FORM_ROUTE } from '@/lib/sales/contact-sales'
import { useStartPlanVisibility } from '@/hooks/use-start-plan-visibility'
import { getVisiblePricingPlans } from '@/lib/pricing/start-plan'
import { withAnalyticsPlanFeatures } from '@/lib/pricing/analytics'
import { useConsoleProfile } from '@/hooks/use-console-profile'
import type { ComparisonCell, ComparisonLinkCell, PlanId, PricingPlan } from '@/lib/pricing/types'
import { cn } from '@/lib/utils'
import {
  analyticsAttrs,
  getPricingPlanCtaAnalyticsAction,
  type AnalyticsActionId,
} from '@/lib/analytics-actions'

export const outlineTierButtonClassName =
  'border-[var(--brand-cta)]/30 text-foreground hover:bg-[var(--brand-cta)]/10 hover:text-foreground'

export const pricingGlassSurfaceClassName =
  'relative isolate overflow-hidden rounded-xl border border-muted-foreground/8 bg-muted-foreground/[0.035] shadow-sm backdrop-blur-sm dark:border-muted/30 dark:bg-muted/10 supports-[backdrop-filter]:bg-muted-foreground/[0.028] supports-[backdrop-filter]:dark:bg-muted/[0.08]'

/** Wider page gutter when Start is shown so four plan cards are not squeezed. */
export const pricingStartPlansContainerClassName =
  'mx-auto w-full max-w-[96rem] px-4 sm:px-6 xl:px-8'

export const pricingThreePlansContainerClassName =
  'mx-auto w-full max-w-7xl px-4 sm:px-6'

export const pricingHeroThreePlansContainerClassName =
  'mx-auto w-full max-w-7xl px-6 sm:px-10 lg:px-14'

/**
 * Keep the cards row on the wider gutter until country is known so 4-plan
 * never expands the container after first paint.
 */
export function getPricingPlanCardsContainerClassName(
  ready: boolean,
  showStartPlan: boolean,
  threePlanClassName: string = pricingThreePlansContainerClassName,
) {
  return !ready || showStartPlan
    ? pricingStartPlansContainerClassName
    : threePlanClassName
}

/** Uniform gap; Pro column wider so the featured card reads larger than neighbors. */
export function getPricingPlanCardsGridClassName(showStartPlan: boolean) {
  return cn(
    'grid gap-6 lg:gap-5 xl:gap-6',
    showStartPlan
      ? 'sm:grid-cols-2 lg:grid-cols-[1fr_1fr_1.12fr_1fr]'
      : 'sm:grid-cols-2 lg:grid-cols-[1fr_1.12fr_1fr]',
  )
}

/** Centers Pro scale in its grid cell without affecting sibling column widths. */
export function PricingPlanCardWrapper({
  featured = false,
  children,
}: {
  featured?: boolean
  children: ReactNode
}) {
  if (!featured) {
    return children
  }

  return (
    <div className="relative z-[1] flex h-full items-center justify-center lg:origin-center lg:scale-[1.06]">
      {children}
    </div>
  )
}

/**
 * Floor for the featured pricing cards row (not stacked mobile height).
 * Covers the taller of 3-col and 4-col at lg: stretched card ~52.7rem and
 * lg:py-6 on the grid (~3rem).
 */
export const pricingHeroCardsReserveClassName =
  'min-h-[42rem] sm:min-h-[54rem] lg:min-h-[54rem]'

/** Home / promo compact plan cards (one row, no feature lists). */
export const pricingCompactCardsReserveClassName =
  'min-h-[17.5rem] sm:min-h-[18.75rem]'

export const pricingPlanCardsFadeClassName =
  'animate-in fade-in-0 slide-in-from-bottom-1 duration-500 ease-out motion-reduce:animate-none'

export function PricingPlanCardsShell({
  ready,
  reserveClassName,
  className,
  children,
}: {
  ready: boolean
  reserveClassName: string
  className?: string
  children: ReactNode
}) {
  return (
    <div className={cn(reserveClassName, className)} aria-busy={!ready || undefined}>
      {ready ? (
        <div className={pricingPlanCardsFadeClassName}>{children}</div>
      ) : null}
    </div>
  )
}

const pricingPlanGlassClassName = pricingGlassSurfaceClassName

function isProPlan(plan: PricingPlan) {
  return plan.id === 'pro'
}

export function getProPlanBadgeLabel(fourPlanGrid: boolean) {
  return fourPlanGrid ? 'Best value' : 'Popular'
}

export function PricingPlanCta({
  plan,
  className,
  size = 'default',
  analyticsAction,
}: {
  plan: Pick<PricingPlan, 'id' | 'cta' | 'ctaVariant' | 'href' | 'internal'>
  className?: string
  size?: 'default' | 'sm'
  /** Override default plan-id mapping (e.g. promo / compare section CTAs). */
  analyticsAction?: AnalyticsActionId
}) {
  const t = useT()
  const buttonClassName = cn(
    size === 'sm' ? 'h-9 text-[12px]' : 'h-10 text-[13px]',
    'w-full',
    plan.ctaVariant === 'outline' && outlineTierButtonClassName,
    className,
  )
  const action =
    analyticsAction ?? getPricingPlanCtaAnalyticsAction(plan.id)
  const analytics = action ? analyticsAttrs(action) : undefined

  if (plan.internal) {
    return (
      <Button variant={plan.ctaVariant} className={buttonClassName} asChild>
        <Link to={plan.href} search={{ redirect: '/' }} {...analytics}>
          {t(plan.cta)}
        </Link>
      </Button>
    )
  }

  return (
    <Button variant={plan.ctaVariant} className={buttonClassName} asChild>
      <a href={plan.href} target="_blank" rel="noopener noreferrer" {...analytics}>
        {t(plan.cta)}
      </a>
    </Button>
  )
}

export function PricingPlanCard({
  plan,
  featured = false,
  badgeLabel,
}: {
  plan: PricingPlan
  featured?: boolean
  badgeLabel?: string
}) {
  const t = useT()
  const isFeatured = featured
  const label = badgeLabel ?? (plan.popular ? 'Popular' : undefined)

  return (
    <article
      className={cn(
        pricingPlanGlassClassName,
        'flex h-full w-full min-w-0 flex-col',
        isFeatured ? 'p-6 shadow-md sm:p-7 lg:p-9' : 'p-6 sm:p-7',
      )}
    >
      <header className="relative z-[1] flex flex-col gap-4">
        <div className="flex flex-wrap items-center gap-2">
          <h2
            className={cn(
              'font-semibold text-foreground',
              isFeatured ? 'text-[16px]' : 'text-[14px]',
            )}
          >
            {t(plan.name)}
          </h2>
          {label ? (
            <span className="rounded-full bg-emerald-500/10 px-2 py-0.5 text-[10px] font-medium text-emerald-600 dark:text-emerald-400">
              {t(label)}
            </span>
          ) : null}
        </div>

        <div className="flex flex-col gap-1">
          {plan.pricePrefix ? (
            <span className="text-[12px] text-muted-foreground">{t(plan.pricePrefix)}</span>
          ) : (
            <span className="hidden text-[12px] sm:block sm:min-h-[1.125rem]" aria-hidden />
          )}
          <p className="flex flex-wrap items-baseline gap-x-1.5">
            <span
              className={cn(
                'font-aeonik-pro font-normal leading-none tracking-tight text-foreground',
                isFeatured
                  ? 'text-[48px] sm:text-[52px] lg:text-[56px]'
                  : 'text-[36px] sm:text-[40px]',
              )}
            >
              {t(plan.price)}
            </span>
            {plan.priceSuffix ? (
              <span
                className={cn(
                  'text-muted-foreground',
                  isFeatured ? 'text-[16px]' : 'text-[14px]',
                )}
              >
                {t(plan.priceSuffix)}
              </span>
            ) : null}
          </p>
        </div>

        {plan.callout ? (
          <p className="rounded-lg border border-border bg-muted/30 px-3 py-2.5 text-[13px] leading-5 text-foreground">
            {t(plan.callout)}
          </p>
        ) : null}

        <p
          className={cn(
            'leading-5 text-muted-foreground',
            isFeatured ? 'min-h-[3.5rem] text-[14px]' : 'min-h-[3.75rem] text-[13px]',
          )}
        >
          {t(plan.description)}
        </p>

        <PricingPlanCta plan={plan} />
      </header>

      <div className="relative z-[1] mt-6 flex min-h-0 flex-1 flex-col gap-3 border-t border-muted-foreground/10 pt-6 dark:border-muted/20">
        {plan.featuresIntro ? (
          <p className="text-[13px] font-medium text-foreground">{t(plan.featuresIntro)}</p>
        ) : (
          <div className="min-h-[1.25rem]" aria-hidden />
        )}
        <ul className={cn('min-h-0 flex-1 space-y-2.5', isFeatured && 'lg:space-y-3')}>
          {plan.features.map((feature) => (
            <li
              key={feature}
              className={cn(
                'flex items-start gap-2.5 text-muted-foreground',
                isFeatured ? 'text-[14px]' : 'text-[13px]',
              )}
            >
              <Check
                className="mt-0.5 size-4 shrink-0 text-[var(--brand-cta)]"
                aria-hidden
              />
              <span>{t(feature)}</span>
            </li>
          ))}
        </ul>
        {plan.footnote ? (
          <p className="mt-auto pt-2 text-[12px] leading-5 text-muted-foreground/80">
            {t(plan.footnote)}
          </p>
        ) : null}
      </div>
    </article>
  )
}

export function PricingCardsGrid() {
  const { ready, showStartPlan } = useStartPlanVisibility()
  const { features } = useConsoleProfile()
  const plans = withAnalyticsPlanFeatures(getVisiblePricingPlans(showStartPlan), features.analytics)
  const proBadgeLabel = getProPlanBadgeLabel(showStartPlan)

  return (
    <PricingPlanCardsShell
      ready={ready}
      reserveClassName={pricingHeroCardsReserveClassName}
    >
      <div
        className={cn(
          getPricingPlanCardsGridClassName(showStartPlan),
          'lg:items-stretch lg:py-6',
        )}
      >
        {plans.map((plan) => {
          const featured = isProPlan(plan)
          return (
            <PricingPlanCardWrapper key={plan.id} featured={featured}>
              <PricingPlanCard
                plan={plan}
                featured={featured}
                badgeLabel={featured ? proBadgeLabel : undefined}
              />
            </PricingPlanCardWrapper>
          )
        })}
      </div>
    </PricingPlanCardsShell>
  )
}

function isLinkCell(value: ComparisonCell): value is ComparisonLinkCell {
  return typeof value === 'object' && value !== null && 'href' in value
}

export function ComparisonCellValue({ value }: { value: ComparisonCell }) {
  const t = useT()
  if (value === true) {
    return (
      <span className="inline-flex size-5 items-center justify-center rounded-full bg-muted">
        <Check className="size-3 text-foreground" aria-hidden />
        <span className="sr-only">{t('Included')}</span>
      </span>
    )
  }

  if (isLinkCell(value)) {
    return (
      <a
        href={value.href}
        className="text-[13px] link-neutral"
        target="_blank"
        rel="noopener noreferrer"
      >
        {t(value.text)}
      </a>
    )
  }

  return (
    <span className="inline-block max-w-full whitespace-normal break-words text-[13px] leading-5 text-muted-foreground">
      {t(value)}
    </span>
  )
}

export function ComparisonRowLabel({
  title,
  info,
}: {
  title: string
  info?: string
}) {
  const t = useT()
  return (
    <div className="flex items-center gap-1.5 text-start">
      <span className="text-[13px] font-medium text-foreground">{t(title)}</span>
      {info ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <button
              type="button"
              className="inline-flex size-5 shrink-0 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
              aria-label={`${t('More about')} ${t(title)}`}
            >
              <Info className="size-3.5" />
            </button>
          </TooltipTrigger>
          <TooltipContent side="top" className="max-w-xs text-[12px] leading-5">
            {t(info)}
          </TooltipContent>
        </Tooltip>
      ) : null}
    </div>
  )
}

export function getPlanCtaHref(planId: PlanId) {
  if (planId === 'enterprise') return SALES_FORM_ROUTE
  return '/sign-up'
}

export function getPlanCtaLabel(planId: PlanId) {
  if (planId === 'enterprise') return 'Contact us'
  return 'Start project'
}
import { getActiveProfileFeatures } from '@/lib/console-profiles'
import {
  getMarketingProductMenuCategories,
  PRODUCT_NAV_REGISTRY,
} from '@/lib/products/registry'
import type { ProductNavItemId } from '@/lib/products/types'

export type MarketingProductToolkitItem = {
  label: string
  href: string
}

function toToolkitItems(ids: readonly ProductNavItemId[]) {
  return ids.map((id) => {
    const item = PRODUCT_NAV_REGISTRY[id]
    return { label: item.name, href: item.href }
  })
}

function getMarketingProductToolkit() {
  const features = getActiveProfileFeatures()
  const categories = getMarketingProductMenuCategories({
    agent: features.agent,
    analytics: features.analytics,
  })
  const byId = Object.fromEntries(categories.map((c) => [c.id, c.productIds])) as Record<
    'build' | 'deploy' | 'protect',
    readonly ProductNavItemId[]
  >

  return {
    build: toToolkitItems(byId.build ?? []),
    deploy: toToolkitItems(byId.deploy ?? []),
    protect: toToolkitItems(byId.protect ?? []),
  } as const
}

